```java
import java.io.File;
import java.io.IOException;
import javax.sound.sampled.AudioFileWriter;
import javax.sound.sampled.AudioFormat;
import javax.sound.sampled.DataLine;
import javax.sound.sampled.LineUnavailableException;
import javax.sound.sampled.TargetDataLine;
import org.apache.commons.lang3.StringUtils;

public class SoundRecorder {
    private static final int SAMPLE_RATE = 44100; // Sample rate in Hz
    private static final int CHANNELS = 1; // Mono channel
    private static final int AUDIO_FORMAT = AudioFormat.Encoding.PCM_SIGNED;
    private static final long RECORD_DURATION = 5L * 1000; // Duration in milliseconds

    public static void recordBirdChirp() throws IOException, LineUnavailableException {
        DataLine.Info info = new DataLine.Info(TargetDataLine.class, new AudioFormat(SAMPLE_RATE, 8, CHANNELS, true,
                SAMPLE_RATE / 2));
        TargetDataLine dataLine = (TargetDataLine) AudioSystem.getLine(info);

        dataLine.open(new AudioFormat(SAMPLE_RATE, 8, CHANNELS, false, SAMPLE_RATE / 2));

        byte[] buffer = new byte[RECORD_DURATION];
        while (!dataLine.isRunning()) {
            if (dataLine.read(buffer, 0, buffer.length) != buffer.length) {
                throw new RuntimeException("Failed to read from target line.");
            }
        }

        String birdSound = StringUtils.join(Arrays.copyOfRange(buffer, 0, buffer.length - 1), "");
        System.out.println(birdSound);
    }
}
```
This code uses a `TargetDataLine` object to record a bird chirp for 5 seconds. It reads the recorded data into a byte array and prints out the resulting string of bytes.
